"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { createMotionLane, useChoreography } from "@/lib/cojeev-motion/choreography";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

export type LivingLinkProps = Omit<React.ComponentProps<"a">, "href"> & {
  href: string;
  /** Anchors have no native disabled attribute: remove href and leave an announced label. */
  disabled?: boolean;
  direction?: "forward" | "up-right";
  /** Directional ink reveals or a soft pigment wash; contour preserves the original resting mark. */
  treatment?: "contour" | "underline-start" | "underline-end" | "underline-center" | "wash-up" | "wash-across";
  tone?: "pink" | "olive" | "blue" | "yellow";
};

/** A native link with an original ink contour. Motion never owns navigation. */
export function LivingLink({
  href, disabled = false, direction = "up-right", treatment = "contour", tone = "blue", children, className, ref,
  onPointerEnter, onPointerLeave, onFocus, onBlur, onClickCapture, onAuxClickCapture,
  "aria-disabled": ariaDisabled, tabIndex, ...props
}: LivingLinkProps) {
  const host = React.useRef<HTMLAnchorElement>(null);
  const lane = React.useRef<ReturnType<typeof createMotionLane> | null>(null);
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const [localQuiet, setLocalQuiet] = React.useState(false);
  const { quiet, transition } = useChoreography();
  const { enabled, inView } = useMotionVisibility(host);
  const blocked = disabled || ariaDisabled === true || ariaDisabled === "true";
  const active = !blocked && (hovered || focused);
  const still = quiet || localQuiet || !enabled || !inView;
  const bindRef = React.useCallback((element: HTMLAnchorElement | null) => {
    host.current = element;
    if (typeof ref === "function") return ref(element);
    if (ref) ref.current = element;
  }, [ref]);

  React.useEffect(() => {
    const element = host.current;
    if (!element) return;
    const painter = createMotionLane(0, value => element.style.setProperty("--link-motion", String(Math.max(0, Math.min(1, value)))));
    lane.current = painter;
    return () => { painter.dispose(); lane.current = null; };
  }, []);
  React.useEffect(() => {
    const element = host.current;
    if (!element) return;
    const update = () => setLocalQuiet(Boolean(element.closest('[data-flow="off"],[data-no-glide]')));
    const observer = new MutationObserver(update);
    for (let ancestor: HTMLElement | null = element; ancestor; ancestor = ancestor.parentElement) {
      observer.observe(ancestor, { attributes: true, attributeFilter: ["data-flow", "data-no-glide"] });
    }
    update();
    return () => observer.disconnect();
  }, []);
  React.useEffect(() => {
    if (still) lane.current?.jump(active ? 1 : 0);
    else lane.current?.to(active ? 1 : 0, transition);
  }, [active, still, transition]);

  return <a {...props} ref={bindRef} href={blocked ? undefined : href} role={blocked ? "link" : props.role}
    data-slot="living-link" data-direction={direction} data-treatment={treatment} data-tone={tone} data-active={active} data-quiet={still}
    aria-disabled={blocked || undefined} tabIndex={blocked ? -1 : tabIndex} className={cn("v-living-link", className)}
    onClickCapture={event => { if (blocked) { event.preventDefault(); event.stopPropagation(); return; } onClickCapture?.(event); }}
    onAuxClickCapture={event => { if (blocked) { event.preventDefault(); event.stopPropagation(); return; } onAuxClickCapture?.(event); }}
    onPointerEnter={event => { onPointerEnter?.(event); if (!event.defaultPrevented && event.pointerType !== "touch") setHovered(true); }}
    onPointerLeave={event => { onPointerLeave?.(event); setHovered(false); }}
    onFocus={event => { onFocus?.(event); if (!event.defaultPrevented) setFocused(true); }}
    onBlur={event => { onBlur?.(event); setFocused(false); }}>
    <span className="v-living-link__words">{children}<svg className="v-living-link__ink" viewBox="0 0 120 12" preserveAspectRatio="none" aria-hidden="true"><path d="M2 8C22 3 37 11 58 7S94 9 118 4" /></svg></span>
    <span className="v-living-link__arrow" aria-hidden="true"><span className="v-living-link__arrow-window">{["outgoing", "incoming"].map(part => <svg key={part} data-arrow={part} viewBox="0 0 20 20"><path d={direction === "forward" ? "M3 10H16M11 5L16 10L11 15" : "M5 15L15 5M6 5H15V14"} /></svg>)}</span></span>
  </a>;
}

"use client";

import * as React from "react";
import { animate, frameSteps, motionValue, type AnimationPlaybackControls, type Transition } from "motion";
import { getMotionTime, isMotionClockFrozen, registerMotionClock } from "@/lib/cojeev-motion/clock";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings, type SettingsSnapshot } from "@/lib/cojeev-motion/settings";
import { useReducedMotion } from "@/lib/cojeev-motion/use-reduced-motion";

/** The shared rhythm. Durations and stagger are seconds, matching Motion's API. */
export const motionTokens = {
  spring: {
    responsive: { type: "spring", stiffness: 360, damping: 32, mass: .85 },
    expressive: { type: "spring", stiffness: 260, damping: 22, mass: 1 },
    gentle: { type: "spring", stiffness: 180, damping: 28, mass: 1 },
  },
  ease: { enter: [.2, .8, .2, 1], exit: [.4, 0, 1, 1], settle: [.2, .65, .25, 1] },
  duration: { quick: .16, enter: .32, exit: .18 },
  stagger: .035,
} as const;

export function resolveChoreography(snapshot: SettingsSnapshot, reduced: boolean): { quiet: boolean; transition: Transition } {
  const quiet = reduced || snapshot.motion.mode === "off" || snapshot.flow.variant === "off";
  if (quiet) return { quiet, transition: { duration: 0, delay: 0 } };
  const speed = snapshot.flow.speed;
  const spring = ["jelly", "rubber", "drop", "pebble"].includes(snapshot.flow.variant)
    ? motionTokens.spring.expressive : motionTokens.spring.responsive;
  return { quiet, transition: { ...spring, stiffness: spring.stiffness * speed * speed, damping: spring.damping * speed } };
}

/** Reactive settings subscription for reusable React surfaces. */
export function useChoreography() {
  const snapshot = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const reduced = useReducedMotion();
  return React.useMemo(() => resolveChoreography(snapshot, reduced), [snapshot, reduced]);
}

/** Connect Motion's JS animations to the existing deterministic document clock. */
export function trackMotion(controls: AnimationPlaybackControls) {
  let origin = getMotionTime() - controls.time * 1000;
  let frozen = isMotionClockFrozen();
  if (frozen) controls.pause();
  const release = registerMotionClock(time => {
    if (time === null) {
      if (frozen) controls.play();
      frozen = false;
      return;
    }
    if (!frozen) {
      origin = time - controls.time * 1000;
      controls.pause();
      frozen = true;
    }
    controls.time = Math.max(0, time - origin) / 1000;
    if (controls.time >= controls.duration) controls.complete();
    // A seek schedules Motion's update phase. Flush it at this explicit sample;
    // normal playback stays entirely on Motion's own animation frame loop.
    frameSteps.update.process({ delta: 0, timestamp: performance.now(), isProcessing: false });
  });
  void controls.finished.then(release, release);
  return () => { release(); controls.stop(); };
}

/** One interruptible spring per scalar; retargets inherit the current value and velocity. */
export function createMotionLane(initial: number, render: (value: number) => void) {
  const value = motionValue(initial);
  const unsubscribe = value.on("change", render);
  let cancel = () => {};
  let generation = 0;
  const stop = () => { generation++; cancel(); cancel = () => {}; value.stop(); };
  const jump = (target: number) => { stop(); value.jump(target); render(target); };
  return {
    get: () => value.get(),
    jump,
    to(target: number, transition: Transition, complete?: () => void) {
      stop();
      if (transition.duration === 0) { jump(target); complete?.(); return; }
      const owner = generation;
      const controls = animate(value, target, {
        ...transition,
        autoplay: !isMotionClockFrozen(),
        onComplete: () => { if (generation === owner) complete?.(); },
      });
      cancel = trackMotion(controls);
    },
    stop,
    dispose: () => { stop(); unsubscribe(); value.destroy(); },
  };
}

/** One document-time clock for springs, cancellable phase timers, then Web Animations. */
export type MotionTimer = {at:number;run:()=>void;native:ReturnType<typeof setTimeout>|null;cancelled:boolean}
let time:number|null=null
const pending=new Set<MotionTimer>()
const drivers=new Set<(time:number|null)=>void>()
const animationStarts=new Map<Animation,{at:number;wasRunning:boolean}>()
const now=()=>time??performance.now()
function arm(timer:MotionTimer){timer.native=setTimeout(()=>{timer.native=null;if(timer.cancelled)return;pending.delete(timer);timer.run()},Math.max(0,timer.at-performance.now()))}
